package com.arjunren.loan.controller;
import com.arjunren.loan.domain.LoanStatus; import com.arjunren.loan.domain.Role; import com.arjunren.loan.dto.Dtos.*; import com.arjunren.loan.entity.AppUser; import com.arjunren.loan.service.LoanService; import jakarta.validation.Valid; import java.util.Map; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api")public class LoanController{private final LoanService loans;public LoanController(LoanService l){loans=l;}@PostMapping("/loans")@ResponseStatus(HttpStatus.CREATED)Map<String,Object>apply(@Valid@RequestBody ApplyRequest r,@AuthenticationPrincipal AppUser u){return Map.of("data",loans.apply(r,u));}@GetMapping("/loans")Map<String,Object>list(@AuthenticationPrincipal AppUser u,@RequestParam(required=false)LoanStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return Map.of("data",loans.list(u,status,page,Math.min(Math.max(size,1),100)));}@GetMapping("/loans/{id}")Map<String,Object>get(@PathVariable Long id,@AuthenticationPrincipal AppUser u){return Map.of("data",loans.get(id,u));}@PatchMapping("/loans/{id}/approve")Map<String,Object>approve(@PathVariable Long id,@Valid@RequestBody ApproveRequest r,@AuthenticationPrincipal AppUser u){return Map.of("data",loans.approve(id,r.annualInterestRate(),u));}@PatchMapping("/loans/{id}/reject")Map<String,Object>reject(@PathVariable Long id,@Valid@RequestBody RejectRequest r,@AuthenticationPrincipal AppUser u){return Map.of("data",loans.reject(id,r.reason(),u));}@PatchMapping("/loans/{id}/disburse")Map<String,Object>disburse(@PathVariable Long id,@AuthenticationPrincipal AppUser u){return Map.of("data",loans.disburse(id,u));}@PostMapping("/loans/{id}/repayments")@ResponseStatus(HttpStatus.CREATED)Map<String,Object>repay(@PathVariable Long id,@Valid@RequestBody RepayRequest r,@AuthenticationPrincipal AppUser u){return Map.of("data",loans.repay(id,r.amount(),u));}@GetMapping("/loans/{id}/repayments")Map<String,Object>payments(@PathVariable Long id,@AuthenticationPrincipal AppUser u,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return Map.of("data",loans.payments(id,u,page,Math.min(Math.max(size,1),100)));}@GetMapping("/dashboard")Map<String,Object>dashboard(@AuthenticationPrincipal AppUser u){if(u.getRole()==Role.CUSTOMER)return Map.of("data",loans.list(u,null,0,100));return Map.of("data",Map.of("pending",loans.count(LoanStatus.PENDING),"disbursed",loans.count(LoanStatus.DISBURSED),"paid",loans.count(LoanStatus.PAID)));}}
